import math


def bellman_ford(edges, n, s, eps=0.0):
    """Bellman-Ford that counts an improvement only if it is larger than eps.
    Returns the list of costs, or None if a negative cycle is reachable from s."""
    dist = [math.inf] * n
    dist[s] = 0
    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v] - eps:
                dist[v] = dist[u] + w
    for u, v, w in edges:
        if dist[u] + w < dist[v] - eps:
            return None
    return dist

